 if($reports.Count -ne $expected){throw 'Missing numerical reports'}
 foreach($x in $reports){
  if(-not $x.redzones_pass -or -not $x.immutable_inputs){throw 'Memory failure'}
  if($x.kind -eq 'moe_expert_order_permutation'){
   if($Which -ne 'expert-test' -or -not $x.exact_permutation -or -not $x.monotonic_experts -or -not $x.all_metadata_checked){throw 'Candidate permutation failure'}
  }elseif($x.kind -eq 'routed_compaction_comparison'){
   if($x.raw_bit_mismatches -ne 0 -or -not $x.prevalidated_float_checked -or -not $x.staged_half_checked -or -not $x.staged_preparation_included -or -not $x.staged_live_views_roundtrip -or $x.replay_lanes -ne 4 -or $x.window_blocks -ne 16384){throw 'Routed replay mismatch'}
   if($x.staged_supported_final_groups -le 0 -or ($x.mode -eq 4 -and $x.staged_unsupported_final_groups -le 0)){throw 'Missing supported or original group coverage'}
   if($Which -eq 'expert-test' -and (-not $x.expert_order_checked -or $x.expert_order_workspace_bytes -ne 16780292)){throw 'Missing expert-ordered replay'}
   if($Which -eq 'routed-test' -and $x.expert_order_checked){throw 'Control unexpectedly reordered'}
  }elseif($x.kind -eq 'prepared_moe_norm_scan'){
   if($x.norm_bit_differences -ne 0 -or -not $x.validate_only -or $x.scaled_fallback){throw 'Original norm mismatch'}
  }else{throw 'Unexpected numerical report'}
 }
 if(@($reports|Where-Object {$_.kind -eq 'prepared_moe_norm_scan'}).Count -ne 2 -or @($reports|Where-Object {$_.kind -eq 'routed_compaction_comparison'}).Count -ne 4){throw 'Missing numerical family'}
 if($Which -eq 'expert-test' -and @($reports|Where-Object {$_.kind -eq 'moe_expert_order_permutation'}).Count -ne 72){throw 'Missing permutation cases'}
}
